"""
    Retrieves the complete session attribute name from the session
    attribute name and the namespace name.

    :type session_attribute_name: String
    :param session_attribute_name: The session attribute name.
    :type namespace_name: String
    :param namespace_name: The namespace name.
    :rtype: String
    :return: The complete session attribute name.
    """
def _get_complete_session_attribute_name(
    session_attribute_name: Any, namespace_name: Any = None
) -> object {
    if not namespace_name {
        return session_attribute_name;
    }
    complete_session_attribute_name = namespace_name + "." + session_attribute_name;
    return complete_session_attribute_name;
}

"""
    Get all publications to an OAIPMH repository for an event.

    :param event: The event
    :type event: dict
    :return: OAIPMH publications
    :rtype: list
    """
def get_oaipmh_publications(event: Any) -> object {
    return [
        (publication["id"], publication["url"])
        for publication in event["publications"]
        if ("oaipmh" in publication["id"])
    ];
}

"""write node BCs

    Args:
        bcdict: dict of node BCs, with DOF values
        bc:  (Default value = "bc.dyn")

    Returns:
        0
    """
def write_bc(bcdict: Any, bc: Any = "bc.dyn") -> object {
    with open(bc, 'w') as bcf {
        bcf.write("$ Generated using bc.py\n");
        bcf.write('*BOUNDARY_SPC_NODE\n');
        for i in bcdict {
            bcf.write(f'{i},0,');
            bcf.write(f'{bcdict[i]}\n');
        }
        bcf.write('*END\n');
    }
    return 0;
}
